-- ZUMUYA GRM: migration additive (ne supprime aucune table existante)
create extension if not exists pgcrypto;
create table if not exists public.grm_orgs(id uuid primary key default gen_random_uuid(), name text not null, kind text not null check(kind in ('restaurant','hotel')), created_by uuid not null default auth.uid(), created_at timestamptz not null default now());
create table if not exists public.grm_members(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','manager','cashier','kitchen','server','inventory')), created_at timestamptz not null default now(), unique(org_id,user_id));
create table if not exists public.grm_items(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, name text not null, category text, unit text not null default 'unité', stock numeric not null default 0, alert_at numeric not null default 0, purchase_cost numeric not null default 0, created_at timestamptz not null default now());
create table if not exists public.grm_stock_moves(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, item_id uuid not null references public.grm_items(id) on delete cascade, kind text not null check(kind in ('in','out','loss','adjust')), quantity numeric not null check(quantity>0), note text, created_by uuid default auth.uid(), created_at timestamptz default now());
create table if not exists public.grm_recipes(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, name text not null, menu_price numeric not null default 0, instructions text, created_at timestamptz default now());
create table if not exists public.grm_recipe_lines(id uuid primary key default gen_random_uuid(), recipe_id uuid not null references public.grm_recipes(id) on delete cascade, item_id uuid not null references public.grm_items(id) on delete cascade, quantity numeric not null check(quantity>0));
create table if not exists public.grm_suppliers(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, name text not null, phone text, email text, notes text, created_at timestamptz default now());
create table if not exists public.grm_purchases(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, supplier_id uuid references public.grm_suppliers(id), status text not null default 'draft' check(status in ('draft','ordered','received','cancelled')), total numeric not null default 0, note text, created_at timestamptz default now());
create table if not exists public.grm_purchase_lines(id uuid primary key default gen_random_uuid(), purchase_id uuid not null references public.grm_purchases(id) on delete cascade, item_id uuid not null references public.grm_items(id), quantity numeric not null check(quantity>0), unit_cost numeric not null default 0);
create table if not exists public.grm_expenses(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, label text not null, category text, amount numeric not null check(amount>=0), paid_at date not null default current_date, payment_method text, note text, created_by uuid default auth.uid(), created_at timestamptz default now());
create table if not exists public.grm_tables(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, label text not null, seats int not null default 2, status text not null default 'available' check(status in ('available','occupied','reserved','maintenance')));
create table if not exists public.grm_reservations(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, table_id uuid references public.grm_tables(id), customer text not null, phone text, party_size int not null default 1, reserved_at timestamptz not null, status text not null default 'booked' check(status in ('booked','seated','completed','cancelled')), notes text);
create table if not exists public.grm_rooms(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, room_number text not null, status text not null default 'available' check(status in ('available','occupied','out_of_service')), unique(org_id,room_number));
create table if not exists public.grm_room_charges(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, room_id uuid not null references public.grm_rooms(id), description text not null, amount numeric not null check(amount>=0), status text not null default 'pending' check(status in ('pending','posted','paid','cancelled')), created_at timestamptz default now());
create table if not exists public.grm_staff(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, name text not null, role text not null, phone text, user_id uuid references auth.users(id), active boolean not null default true);
create table if not exists public.grm_sales(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, total numeric not null check(total>=0), payment_method text, source text not null default 'pos', created_by uuid default auth.uid(), created_at timestamptz default now());
create table if not exists public.grm_audit(id uuid primary key default gen_random_uuid(), org_id uuid not null references public.grm_orgs(id) on delete cascade, action text not null, entity text, entity_id uuid, details jsonb default '{}'::jsonb, created_by uuid default auth.uid(), created_at timestamptz default now());
create or replace function public.grm_is_member(p_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from grm_members where org_id=p_org and user_id=auth.uid()) $$;
create or replace function public.grm_is_manager(p_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from grm_members where org_id=p_org and user_id=auth.uid() and role in ('owner','manager')) $$;
create or replace function public.grm_add_org(p_name text,p_kind text) returns uuid language plpgsql security definer set search_path=public as $$ declare v uuid; begin if auth.uid() is null then raise exception 'Authentication required'; end if; if p_kind not in ('restaurant','hotel') then raise exception 'Invalid organization type'; end if; insert into grm_orgs(name,kind,created_by) values(trim(p_name),p_kind,auth.uid()) returning id into v; insert into grm_members(org_id,user_id,role) values(v,auth.uid(),'owner'); return v; end $$;
-- RLS enabled; member-scoped policies. Recipe lines/purchase lines are protected through their parent org.
do $$ declare t text; begin foreach t in array array['grm_orgs','grm_members','grm_items','grm_stock_moves','grm_recipes','grm_recipe_lines','grm_suppliers','grm_purchases','grm_purchase_lines','grm_expenses','grm_tables','grm_reservations','grm_rooms','grm_room_charges','grm_staff','grm_sales','grm_audit'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
do $$ begin
create policy grm_orgs_member on grm_orgs for select using (grm_is_member(id));
create policy grm_orgs_owner on grm_orgs for update using (grm_is_manager(id));
create policy grm_members_member on grm_members for select using (grm_is_member(org_id));
create policy grm_members_manager on grm_members for all using (grm_is_manager(org_id)) with check (grm_is_manager(org_id));
create policy grm_items_member on grm_items for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_stock_member on grm_stock_moves for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_recipes_member on grm_recipes for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_recipe_lines_member on grm_recipe_lines for all using (exists(select 1 from grm_recipes r where r.id=recipe_id and grm_is_member(r.org_id))) with check (exists(select 1 from grm_recipes r where r.id=recipe_id and grm_is_member(r.org_id)));
create policy grm_suppliers_member on grm_suppliers for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_purchases_member on grm_purchases for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_purchase_lines_member on grm_purchase_lines for all using (exists(select 1 from grm_purchases p where p.id=purchase_id and grm_is_member(p.org_id))) with check (exists(select 1 from grm_purchases p where p.id=purchase_id and grm_is_member(p.org_id)));
create policy grm_expenses_member on grm_expenses for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_tables_member on grm_tables for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_reservations_member on grm_reservations for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_rooms_member on grm_rooms for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_room_charges_member on grm_room_charges for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_staff_member on grm_staff for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_sales_member on grm_sales for all using (grm_is_member(org_id)) with check (grm_is_member(org_id));
create policy grm_audit_member on grm_audit for select using (grm_is_member(org_id));
exception when duplicate_object then null; end $$;
grant execute on function public.grm_add_org(text,text) to authenticated;
grant execute on function public.grm_is_member(uuid) to authenticated;
grant execute on function public.grm_is_manager(uuid) to authenticated;
